function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // bird flying
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t)*50, H/2 + Math.cos(t)*20, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t)*50, H/2 + Math.cos(t)*20);
  ctx.lineTo(W/2 + Math.sin(t)*50 + Math.sin(t)*20, H/2 + Math.cos(t)*20 + Math.cos(t)*10);
  ctx.stroke();

  // fish swimming
  ctx.beginPath();
  ctx.arc(W/2 + Math.cos(t)*30, H - 50 + Math.sin(t)*10, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.cos(t)*30, H - 50 + Math.sin(t)*10);
  ctx.lineTo(W/2 + Math.cos(t)*30 + Math.cos(t)*15, H - 50 + Math.sin(t)*10 + Math.sin(t)*5);
  ctx.stroke();

  // rabbit hopping
  ctx.beginPath();
  ctx.arc(W - 100 + Math.sin(t)*20, H/2 + Math.cos(t)*30, 15, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W - 100 + Math.sin(t)*20, H/2 + Math.cos(t)*30);
  ctx.lineTo(W - 100 + Math.sin(t)*20 + Math.sin(t)*10, H/2 + Math.cos(t)*30 + Math.cos(t)*10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - 100 + Math.sin(t)*20, H/2 + Math.cos(t)*30 + 10);
  ctx.lineTo(W - 100 + Math.sin(t)*20 + Math.sin(t)*10, H/2 + Math.cos(t)*30 + Math.cos(t)*10 + 10);
  ctx.stroke();

  ctx.restore();
}
